    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    separators = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != background]
    if not separators:
        return [row[:] for row in grid]
    bands = []
    start = 0
    for r in separators:
        if r > start:
            bands.append((start, r))
        start = r + 1
    if start < h:
        bands.append((start, h))
    if not bands:
        return [row[:] for row in grid]
    size = min(end - start for start, end in bands)
    template = {}
    for start, end in bands:
        for dr in range(min(size, end-start)):
            for c, value in enumerate(grid[start+dr]):
                if value != background:
                    template.setdefault((dr, c), value)
    out = [row[:] for row in grid]
    for start, end in bands:
        for (dr, c), value in template.items():
            if dr < end-start and out[start+dr][c] == background:
                out[start+dr][c] = value
    return out
'''
